const proveUserEmail = `-- name: ProveUserEmail :execrows
UPDATE users SET email_proven = 1 WHERE id = +? AND NOT email_proven
`

// ProveUserEmail records that the account's email reaches its owner; 1
// row when it wasn't proven before.
func (q *Queries) ProveUserEmail(ctx context.Context, id int64) (int64, error) {
	result, err := q.db.ExecContext(ctx, proveUserEmail, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const revokeToken = `-- name: RevokeToken :exec
UPDATE tokens SET revoked_at = ? WHERE id = +? AND revoked_at IS NULL
`

type RevokeTokenParams struct {
	RevokedAt *time.Time
	ID        int64
}

func (q *Queries) RevokeToken(ctx context.Context, arg RevokeTokenParams) error {
	_, err := q.db.ExecContext(ctx, revokeToken, arg.RevokedAt, arg.ID)
	return err
}

const revokeUserLoginTokens = `-- name: RevokeUserLoginTokens :execrows
UPDATE tokens SET revoked_at = +?1
WHERE user_id = +?2 AND origin = 'cli_login' AND revoked_at IS NULL AND id != +?3
`

type RevokeUserLoginTokensParams struct {
	Now    *time.Time
	UserID *int64
	Keep   int64
}

// RevokeUserLoginTokens revokes the `dock login` tokens acting for a user,
// except token keep (0: none).
func (q *Queries) RevokeUserLoginTokens(ctx context.Context, arg RevokeUserLoginTokensParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, revokeUserLoginTokens, arg.Now, arg.UserID, arg.Keep)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const revokeUserTokens = `-- name: RevokeUserTokens :many
UPDATE tokens SET revoked_at = +?1
WHERE user_id = +?2 AND revoked_at IS NULL
RETURNING id
`

type RevokeUserTokensParams struct {
	Now    *time.Time
	UserID *int64
}

// RevokeUserTokens revokes every token a user holds or made by hand and
// returns their IDs.
func (q *Queries) RevokeUserTokens(ctx context.Context, arg RevokeUserTokensParams) ([]int64, error) {
	rows, err := q.db.QueryContext(ctx, revokeUserTokens, arg.Now, arg.UserID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []int64
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

